import{c as o,J as r,h as s,k as a}from"./chunks/framework.WgZQdPFo.js";const h=JSON.parse('{"title":"Личные операции","description":"Журнал учета крупных личных доходов, изъятий, инвестиционных транзакций и переводов между счетами.","frontmatter":{"title":"Личные операции","description":"Журнал учета крупных личных доходов, изъятий, инвестиционных транзакций и переводов между счетами.","order":20},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/operations.md","filePath":"ru/docs/spaces/moy-kapital/operations.md"}'),l={name:"ru/docs/spaces/moy-kapital/operations.md"};function i(n,t,e,g,p,c){return r(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="личные-операции" tabindex="-1">Личные операции <a class="header-anchor" href="#личные-операции" aria-label="Permalink to &quot;Личные операции&quot;">​</a></h1><p>Вкладка <strong>«Личные операции»</strong> — это журнал значимых финансовых событий личного контура мастера. Она предназначена не для рутинных бытовых чеков (которые автоматически учитываются математической дельтой), а для фиксации <strong>крупных целевых движений денег</strong>, формирующих общую картину благосостояния.</p><hr><h2 id="философия-журнала-операции" tabindex="-1">Философия журнала операций <a class="header-anchor" href="#философия-журнала-операции" aria-label="Permalink to &quot;Философия журнала операций&quot;">​</a></h2><p>Главный принцип ОмниКрафт ЕРП — экономия времени мастера. Мы не требуем вносить каждую чашку кофе или заправку автомобиля.</p><p>В журнал заносятся только фундаментальные операции:</p><ul><li><strong>Дивиденды и изъятия из цеха:</strong> вывод чистой прибыли из производственного пространства на личную карту мастера.</li><li><strong>Вливания в бизнес:</strong> личные займы или довнесение капитала в кассу мастерской на закупку оборудования или сырья.</li><li><strong>Крупные доходы извне:</strong> поступления от сдачи недвижимости, сторонние консалтинговые гонорары, продажа автомобиля.</li><li><strong>Крупные капитальные расходы:</strong> покупка недвижимости, дорогостоящее лечение, ремонт дома или приобретение автомобиля.</li><li><strong>Переводы между счетами и кошельками:</strong> конвертация валюты, пополнение брокерского счета или криптокошелька.</li></ul><div class="info custom-block"><p class="custom-block-title">Защита от искажения дельты</p><p>Фиксация крупного дохода (например, от продажи старого автомобиля) объясняет программе резкий скачок баланса на счетах и защищает расчет текущих производственных расходов от математических искажений.</p></div><hr><h2 id="создание-операции" tabindex="-1">Создание операции <a class="header-anchor" href="#создание-операции" aria-label="Permalink to &quot;Создание операции&quot;">​</a></h2><p>Для регистрации движения средств нажмите кнопку <strong>«Добавить операцию»</strong>:</p><ol><li><strong>Тип операции:</strong><ul><li><strong>Доход:</strong> увеличение капитала из внешних источников.</li><li><strong>Расход:</strong> целевое крупное списание личных средств.</li><li><strong>Перевод:</strong> нейтральное перемещение денег между своими счетами или конвертация валюты.</li></ul></li><li><strong>Сумма и валюта:</strong> размер транзакции и валюта счета.</li><li><strong>Счет списания / пополнения:</strong> выбор из зарегистрированных счетов и кошельков.</li><li><strong>Статья (Категория):</strong> выбор из встроенного каталога статей («Дивиденды бизнеса», «Инвестиции», «Крупные покупки», «Налоги», «Семья»).</li><li><strong>Дата и время:</strong> дата проведения платежа.</li><li><strong>Комментарий:</strong> уточняющие детали (например, «Аванс за консультации по кожевенному ремеслу»).</li></ol><hr><h2 id="фильтрация-и-экспорт-данных" tabindex="-1">Фильтрация и экспорт данных <a class="header-anchor" href="#фильтрация-и-экспорт-данных" aria-label="Permalink to &quot;Фильтрация и экспорт данных&quot;">​</a></h2><p>В шапке журнала предусмотрены быстрые фильтры:</p><ul><li><strong>Период времени:</strong> фильтрация за текущий месяц, квартал, год или произвольный диапазон дат.</li><li><strong>Категории и типы:</strong> изоляция только доходов или только расходов.</li><li><strong>Поиск по комментариям:</strong> мгновенный отбор записей по названию контрагента или ключевому слову.</li></ul>',16)])])}const u=o(l,[["render",i]]);export{h as __pageData,u as default};
